SELECT compound_structures.canonical_smiles, compound_records.compound_name, metabolism.met_conversion, metabolism.pathway_key FROM metabolism JOIN compound_records ON metabolism.substrate_record_id = compound_records.record_id JOIN compound_structures ON compound_records.molregno = compound_structures.molregno ORDER BY compound_structures.canonical_smiles ASC, compound_records.compound_name ASC, metabolism.met_conversion ASC, metabolism.pathway_key ASC LIMIT 200
